{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Loxapine, the closest structural analogue sharing the chlorinated dibenzoxazepine core, has human systemic availability of 29%, which is above the 20% threshold despite substantial first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Tianeptine, a tricyclic antidepressant with a basic amine, is essentially completely absorbed orally with an absolute bioavailability of about 99%, supporting high oral bioavailability for this lipophilic amine class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Clobazam, a lipophilic heterocyclic drug with a chloro substituent, has oral bioavailability of about 90%, supporting high F for structurally related lipophilic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Prochlorperazine, a lipophilic tricyclic with a basic piperazine and chloro substituent, has absolute oral bioavailability of only 12.5%, indicating that such structures can undergo extensive first-pass metabolism.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C28"],
      "claim": "Clomipramine, a chlorinated tricyclic antidepressant with a tertiary amine, has absolute oral bioavailability around 48%, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Mirtazapine, a tetracyclic antidepressant with a basic N-methyl piperazine, has absolute oral bioavailability of about 50%, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue loxapine has F=29%, above the 20% threshold, and most moderately similar lipophilic basic amines (tianeptine, clobazam, clomipramine, mirtazapine, sertraline, tolvaptan) show F >= 20%. Only prochlorperazine is clearly low, but its lower structural similarity reduces its weight. The query's favorable physicochemical profile (low MW, very low TPSA, no HBD, rigid structure) further supports high oral bioavailability.",
  "evidence_gaps": [
    "No direct human bioavailability data exist for the query molecule.",
    "The closest analogue loxapine has F=29%, close to the 20% threshold, so the margin is uncertain.",
    "Metabolic stability of the spiro-azetidine moiety relative to piperazine or other basic amine side chains is unknown.",
    "First-pass extraction could vary substantially with small structural changes, as seen between loxapine and prochlorperazine."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

